(async () => {
'use strict';
await window.CircuitStore.ready;
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topics=window.COURSE_TOPICS, methods=window.METHODS, questions=window.QUESTIONS;
const compactNavigation=matchMedia('(max-width:700px)');
let focusNavigationOpen=false;
let readingSize=22;try{const saved=Number(localStorage.getItem('circuit-reading-size'));if(saved>=18&&saved<=30)readingSize=saved;}catch{}
document.documentElement.style.setProperty('--reading-size',readingSize+'px');
function bindReadingControls(){
 const smaller=$('#reading-smaller'),larger=$('#reading-larger');if(!smaller)return;
 const refresh=()=>{document.documentElement.style.setProperty('--reading-size',readingSize+'px');$('#reading-size-value').textContent=readingSize+'px';smaller.disabled=readingSize<=18;larger.disabled=readingSize>=30;};
 const change=amount=>{readingSize=Math.max(18,Math.min(30,readingSize+amount));try{localStorage.setItem('circuit-reading-size',String(readingSize));}catch{}refresh();};
 smaller.onclick=()=>change(-2);larger.onclick=()=>change(2);refresh();
 document.querySelectorAll('.article img').forEach(image=>{image.tabIndex=0;image.setAttribute('role','button');image.setAttribute('aria-label','Enlarge '+(image.alt||'lesson diagram'));image.title='Click to enlarge diagram';const enlarge=()=>openModal('<img class="diagram-expanded" src="'+esc(image.getAttribute('src'))+'" alt="'+esc(image.alt||'Lesson diagram')+'">');image.onclick=enlarge;image.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();enlarge();}};});
}

let sidebarCollapsed=false;try{sidebarCollapsed=localStorage.getItem('circuit-sidebar-collapsed')==='true';}catch{}
function updateSidebar(){
 const focused=['chapter','topic'].includes(location.hash.slice(1).split('/')[0]);
 document.documentElement.classList.toggle('focus-reading',focused);
 document.documentElement.classList.toggle('sidebar-collapsed',focused?!focusNavigationOpen:sidebarCollapsed);
 const toggle=$('.menu-btn');if(!toggle)return;
 const shown=compactNavigation.matches?$('.sidebar').classList.contains('open'):(focused?focusNavigationOpen:!sidebarCollapsed);
 toggle.setAttribute('aria-expanded',String(shown));toggle.setAttribute('aria-label',shown?'Hide navigation panel':'Show navigation panel');toggle.title=shown?'Hide navigation panel':'Show navigation panel';
}
compactNavigation.addEventListener('change',()=>{$('.sidebar')?.classList.remove('open');$('#scrim')?.classList.remove('show');updateSidebar();});

const chapterNames=['','Basic concepts & laws','Transient analysis','AC circuits'];
let state={reviewed:[],attempts:{},lastTopic:'1.1',...CircuitStore.get('app')};if(!Array.isArray(state.reviewed))state.reviewed=[];if(!state.attempts||typeof state.attempts!=='object')state.attempts={};
const save=()=>CircuitStore.set('app',state);
window.addEventListener('circuit-study-external',()=>{const shared=CircuitStore.get('app');if(shared&&Array.isArray(shared.reviewed)&&shared.attempts)state=shared;});
const topic=id=>topics.find(t=>t.id===id), link=(id,label)=>`<a class="text-link" href="#topic/${id}">${esc(label||('Read lesson '+id))} ↗</a>`;
const button=(url,label,kind='')=>`<a class="button ${kind}" href="${url}">${label}</a>`;
const pdf='<a class="button" href="reviewed-course.pdf" target="_blank" rel="noopener">Reviewed PDF ↗</a>';
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
function parseNumber(s){s=String(s).trim().replace(/−/g,'-');if(/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(s))return Number(s);const m=s.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*\/\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+))$/);return m&&Number(m[2])!==0?Number(m[1])/Number(m[2]):null}
const rc=(r,c,t)=>({tau:r*c,voltage:10*(1-Math.exp(-t)),current:10/r*Math.exp(-t)});
function phasor(r,l,c,u=100){let x=l-c,z=Math.hypot(r,x),angle=Math.atan2(x,r)*180/Math.PI,i=z?u/z:null;return{x,z,angle,i,p:i===null?null:i*i*r,q:i===null?null:i*i*x}}
window.STUDY_CORE={parseNumber,rc,phasor};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
const circuit=`<svg viewBox="0 0 420 270" class="lab-svg" role="img" aria-label="A resistor and capacitor circuit with an exponential charging curve"><defs><pattern id="dots" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#b4c4b6"/></pattern></defs><rect width="420" height="270" fill="url(#dots)"/><g fill="none" stroke="#20594d" stroke-width="3" stroke-linejoin="round"><path d="M65 110V55H145l8-12 12 24 12-24 12 24 12-24 8 12h94v52M303 123v65H65v-48"/><circle cx="65" cy="125" r="16"/><path d="M57 125h16m-8-8v16m220-26h36m-36 16h36"/><path d="M105 218h245M105 218v-90" stroke-width="1"/><path d="M106 217C140 163 190 146 320 145" stroke="#aa6246"/></g><g fill="#20594d" font-family="monospace" font-size="15"><text x="165" y="31">R</text><text x="332" y="120">C</text><text x="29" y="130">U</text><text x="328" y="220">t</text><text x="245" y="173" fill="#aa6246">1 − e⁻ᵗ/τ</text></g></svg>`;
const navs=[['desk','Study desk','⌂'],['methods','Problem finder','⌕'],['chapters','Course library','▤'],['practice','Practice','◎'],['lab','Visual lab','⌁'],['exam','Exam sheet','≡']];
function shell(route){$('#app').innerHTML=`<div class="mobile-scrim" id="scrim"></div><aside class="sidebar" id="circuit-sidebar"><a class="brand" href="#desk"><img class="brandmark" src="icon.svg" alt=""><span>Circuit<small>EXAM STUDIO</small></span></a><div class="navlabel">YOUR WORKSPACE</div><nav class="nav">${navs.map(([id,label,icon])=>`<a href="#${id}" class="${(route===id.split('/')[0]||(id==='chapters'&&['chapter','topic'].includes(route)))?'active':''}"><span class="icon">${icon}</span>${label}</a>`).join('')}</nav><div class="side-bottom"><div class="source-badge"><span class="dot"></span> Built from your course</div><p class="tiny">3 chapters · 21 topics<br>330 reviewed slide pages<br>Experiments excluded</p><button class="text-link" id="about">How to use this studio ↗</button></div></aside><header class="topbar"><div class="breadcrumb"><button class="menu-btn" type="button" aria-label="Toggle navigation panel" aria-controls="circuit-sidebar">☰</button>My workspace <span>/</span> ${(['chapter','topic'].includes(route)?'Focused reading':navs.find(n=>n[0].split('/')[0]===route)?.[1])||'Study desk'}</div><div class="top-right"><button class="search-launch" id="search"><span>⌕</span> Search everything <kbd>/</kbd></button><a class="pill" href="#exam">Open-book mode ↗</a></div></header><main class="main" id="main"></main>`;
$('#search').onclick=openSearch;$('#about').onclick=about;$('.menu-btn').onclick=()=>{if(compactNavigation.matches){$('.sidebar').classList.toggle('open');$('#scrim').classList.toggle('show');}else if(['chapter','topic'].includes(location.hash.slice(1).split('/')[0])){focusNavigationOpen=!focusNavigationOpen;}else{sidebarCollapsed=!sidebarCollapsed;try{localStorage.setItem('circuit-sidebar-collapsed',String(sidebarCollapsed));}catch{}}updateSidebar();};$('#scrim').onclick=()=>{$('.sidebar').classList.remove('open');$('#scrim').classList.remove('show');updateSidebar();};updateSidebar();}
function desk(){const tried=Object.keys(state.attempts).length,weak=Object.entries(state.attempts).filter(([,v])=>!v.lastCorrect).length;
return `<section class="hero"><div class="hero-copy"><div class="eyebrow">OPEN BOOK. CLEAR MIND.</div><h1>Understand the circuit.<br>Find your next step.</h1><p>Your complete course, organized around the decisions you make when solving a problem. Learn the idea, follow a method, then check it yourself.</p><div class="button-row">${button('#methods','Find a solving method →','primary')}${button('#practice','Start a practice session')}</div><div class="reviewed-marker">✓ Every theory lesson reviewed · source-linked explanations</div></div><div class="hero-art">${circuit}<span class="art-label">ONE CIRCUIT. A FEW CLEAR STEPS.</span></div></section><div class="section-head"><div><div class="eyebrow">THE COMPLETE PICTURE</div><h2>Your three chapters</h2></div>${button('#topic/'+state.lastTopic,'Continue reading ↗','small')}</div><div class="grid3">${[1,2,3].map((c)=>{let ts=topics.filter(t=>t.chapter===c),done=ts.filter(t=>state.reviewed.includes(t.id)).length;return `<a class="chapter-card" href="#chapter/${c}"><div class="chapter-top"><span class="chapter-icon c${c}">${['','↔','⌁','∿'][c]}</span><span class="chapter-num">0${c}</span></div><h3>${chapterNames[c]}</h3><p>${['','References, sources, circuit laws, superposition and Thévenin.','Continuity, time constants and the universal first-order response.','Sine-based phasors, impedance, series/parallel circuits and power.'][c]}</p><div class="card-footer"><span>${ts.length} topics · ${[0,159,100,71][c]} slide pages</span><span>${done}/${ts.length} reviewed →</span></div></a>`}).join('')}</div><div class="lower-grid"><section class="panel"><div class="section-head"><h2>What does your problem ask?</h2><a class="text-link" href="#methods">All methods →</a></div>${['thevenin','transient','phasor'].map((id,i)=>{let m=methods.find(x=>x.id===id);return `<a class="method-row" href="#method/${id}"><span class="num">0${i+1}</span><div><h4>${m.title}</h4><p>${m.cue}</p></div><span class="arrow">↗</span></a>`}).join('')}</section><section class="panel"><div class="eyebrow">YOUR PROGRESS, ON THIS DEVICE</div><h2>Build confidence by checking.</h2><div class="stats-line"><strong>${state.reviewed.length}<span class="muted"> / 21</span></strong><span>topics marked reviewed</span></div><div class="progressbar"><span style="width:${state.reviewed.length/21*100}%"></span></div><p>${tried} of 36 questions attempted · ${weak} to revisit</p><div class="button-row">${button(weak?'#practice/mistakes':'#practice',weak?'Revisit mistakes →':'Try a short session →','primary small')}</div><p class="tiny muted">Progress records your activity, not a prediction of your exam score.</p></section></div><div class="mini-note"><strong>For your open-book exam:</strong> start with the problem finder or exam sheet. Keep the full explanation one click away. ${pdf}</div>`}
function methodCards(list){return list.map(m=>`<a class="method-card" href="#method/${m.id}"><span class="chapter-tag">CHAPTER ${m.chapter} · ${m.time}</span><h3>${m.title}</h3><p>${m.cue}</p><div class="formula-chip">${m.formula}</div><div class="card-footer"><span>See the method</span><span>↗</span></div></a>`).join('')}
function methodsPage(){return `<div class="page-intro"><div class="eyebrow">FROM QUESTION TO EQUATION</div><h1>Find your solving method.</h1><p>Choose the pattern you recognize in your question. Each method includes a sequence, a worked example and the trap to avoid.</p></div><input class="route-search" id="method-search" type="search" placeholder="Try “time constant”, “load current”, or “power”…" aria-label="Search solving methods"><div class="filter-row">${[0,1,2,3].map(c=>`<button class="filter ${c===0?'active':''}" data-chapter="${c}">${c?chapterNames[c]:'All methods'}</button>`).join('')}</div><div class="methods-grid" id="method-results">${methodCards(methods)}</div>`}
function methodDetail(id){let m=methods.find(x=>x.id===id);if(!m)return methodsPage();return `<a class="backlink" href="#methods">← All solving methods</a><div class="method-layout"><section><span class="chapter-tag">CHAPTER ${m.chapter} · LESSON ${m.topic}</span><h1 class="method-title">${m.title}</h1><p class="muted">${m.cue}</p><div class="formula-big">${m.formula}</div><p>${m.why}</p><h2>Follow these steps</h2>${m.steps.map((s,i)=>`<div class="step"><span class="step-num">${i+1}</span><p>${s}</p></div>`).join('')}<div class="callout"><strong>Watch the trap</strong><p>${m.trap}</p></div><div class="callout green"><strong>Check before moving on</strong><p>${m.check}</p></div></section><aside class="sticky"><div class="panel example"><div class="eyebrow">WORKED EXAMPLE</div><h3>Put it into practice</h3><p>${m.example}</p><div class="button-row">${button('#practice/topic/'+m.topic,'Test this idea →','primary small')}</div><p>${link(m.topic,'Open the complete lesson')}</p></div><div class="mini-note">Use the full lesson for diagrams, derivations and additional examples.</div></aside></div>`}
function chaptersPage(){return `<a class="backlink" href="#desk">← Study desk</a><div class="page-intro"><div class="eyebrow">YOUR COMPLETE COURSE</div><h1>Choose a chapter.</h1><p>Open one chapter, then focus on one lesson at a time.</p></div><div class="grid3">${[1,2,3].map(c=>{const list=topics.filter(t=>t.chapter===c);return `<a class="chapter-card" href="#chapter/${c}"><span class="chapter-tag">CHAPTER ${c}</span><h2>${chapterNames[c]}</h2><p>${list.length} lessons</p><span class="text-link">Open chapter →</span></a>`}).join('')}</div>`;}
function chapterPage(id){const c=[1,2,3].includes(Number(id))?Number(id):1,list=topics.filter(t=>t.chapter===c);return `<a class="backlink" href="#chapters">← All chapters</a><div class="page-intro"><div class="eyebrow">CHAPTER ${c} · ${list.length} LESSONS</div><h1>${chapterNames[c]}</h1><p>Choose a lesson to read on its own. Your place and review marks stay saved.</p></div><div class="focus-topics">${list.map(t=>`<a class="panel focus-topic" href="#topic/${t.id}"><span class="chapter-tag">${t.id}</span><h2>${esc(t.title)}</h2><span class="text-link">${state.reviewed.includes(t.id)?'✓ Reviewed · Read again':'Read this lesson'} →</span></a>`).join('')}</div>`;}
function library(id){const t=topic(id)||topics[0];state.lastTopic=t.id;save();let n=topics.indexOf(t),reviewed=state.reviewed.includes(t.id);return `<div class="focus-backlinks"><a class="backlink" href="#chapter/${t.chapter}">← Chapter ${t.chapter}: ${chapterNames[t.chapter]}</a><a class="text-link" href="#chapters">All chapters</a></div><div class="library"><article class="reading"><div class="reading-top"><span class="chapter-tag">CHAPTER ${t.chapter} · LESSON ${t.id}</span><button class="button small" id="review-topic">${reviewed?'✓ Reviewed':'Mark as reviewed'}</button></div><h1 class="topic-title">${esc(t.title)}</h1><div class="reading-toolbar"><span>Comfortable reading</span><div class="reading-size-controls" role="group" aria-label="Lesson text size"><button type="button" id="reading-smaller" aria-label="Decrease lesson text size">A−</button><output id="reading-size-value" aria-live="polite">${readingSize}px</output><button type="button" id="reading-larger" aria-label="Increase lesson text size">A+</button></div></div><div class="article">${t.html}</div><div class="callout green"><strong>Ready to check your understanding?</strong><div class="button-row">${button('#practice/topic/'+t.id,'Practice this lesson →','primary small')}${methods.filter(m=>m.topic===t.id).map(m=>button('#method/'+m.id,m.title+' ↗','small')).join('')}</div></div><div class="topic-footer">${n?button('#topic/'+topics[n-1].id,'← '+topics[n-1].id+' Previous'):'<span></span>'}${n<topics.length-1?button('#topic/'+topics[n+1].id,'Next '+topics[n+1].id+' →'):button('#exam','Open exam sheet →')}</div></article></div>`}
function restoreQuiz(){try{const q=CircuitStore.get('quiz');if(!q||!Array.isArray(q.ids)||q.ids.length>36)return null;const list=q.ids.map(id=>questions.find(x=>x.id===id));if(!list.length||list.some(q=>!q)||!Number.isInteger(q.index)||q.index<0||q.index>list.length)return null;const current=list[q.index],order=q.order;if(current?.type==='choice'&&order!==null&&(!Array.isArray(order)||order.length!==current.choices.length||new Set(order).size!==order.length||order.some(i=>!Number.isInteger(i)||i<0||i>=current.choices.length)))return null;const answers=Array.isArray(q.answers)?q.answers.filter(a=>a&&questions.some(x=>x.id===a.id)&&typeof a.correct==='boolean'&&Number.isFinite(a.given)):[];return{list,index:q.index,score:answers.filter(a=>a.correct).length,answers,filter:typeof q.filter==='string'?q.filter:'',selected:Number.isInteger(q.selected)?q.selected:null,checked:q.checked===true&&answers.length>q.index,order:Array.isArray(order)?order:null,numericText:typeof q.numericText==='string'?q.numericText.slice(0,100):''};}catch{return null;}}
let quiz=restoreQuiz();
function saveQuiz(){CircuitStore.set('quiz',quiz?{...quiz,list:undefined,ids:quiz.list.map(q=>q.id)}:null);}
function practiceIntro(filter=''){let pool=filter==='mistakes'?questions.filter(q=>state.attempts[q.id]&&!state.attempts[q.id].lastCorrect):filter.startsWith('topic/')?questions.filter(q=>q.topic===filter.slice(6)):questions;return `<div class="page-intro"><div class="eyebrow">RETRIEVE → CHECK → REPAIR</div><h1>A little practice. A clearer picture.</h1><p>Try each question before looking back. You’ll get an explanation and a direct link to its lesson after every answer.</p></div><div class="question-layout"><section class="panel quiz-intro"><span class="chapter-tag">${filter==='mistakes'?'YOUR REVIEW QUEUE':filter.startsWith('topic/')?'LESSON '+esc(filter.slice(6)):'36 QUESTIONS · ALL THREE CHAPTERS'}</span><h2>${filter?'A focused practice session':'Choose your practice session'}</h2>${filter?'':`<label for="quiz-chapter">Chapter</label><select id="quiz-chapter"><option value="0">All three chapters</option>${[1,2,3].map(c=>`<option value="${c}">${chapterNames[c]}</option>`).join('')}</select>`}<p>${pool.length?`${pool.length} questions available${filter?' in this selection':''}. A short session takes up to 10 questions.`:'No questions are waiting here. Read the lesson, then try the complete practice bank.'}</p><div class="button-row"><button class="button primary" id="start-quiz" ${pool.length?'':'disabled'}>Start a short session →</button><button class="button" id="start-all" ${pool.length?'':'disabled'}>Use all questions</button></div><p class="tiny muted">Numeric questions show the unit to use. Decimals, scientific notation and simple fractions are accepted.</p></section><aside class="panel"><h3>Make the next attempt count.</h3><p>1. Choose a reference and name the unknown.</p><p>2. Write the equation before calculating.</p><p>3. Check signs, units and limiting cases.</p><div class="callout green">Open book? First locate the right method. Then use the book to verify your steps.</div><a class="text-link" href="#practice/mistakes">Revisit my mistakes ↗</a></aside></div>`}
function beginQuiz(all=false,filter=''){let c=Number($('#quiz-chapter')?.value||0),pool=questions.filter(q=>(!c||q.chapter===c)&&(filter==='mistakes'?(state.attempts[q.id]&&!state.attempts[q.id].lastCorrect):filter.startsWith('topic/')?q.topic===filter.slice(6):true));quiz={list:shuffle(pool).slice(0,all?999:10),index:0,score:0,answers:[],selected:null,checked:false,order:null,numericText:'',filter};saveQuiz();if(quiz.list.length)drawQuestion()}
function drawQuestion(){let q=quiz.list[quiz.index];quiz.order??=q.type==='choice'?shuffle(q.choices.map((_,i)=>i)):[];$('#main').innerHTML=`<a class="backlink" id="end-session" href="#practice">← End session</a><div class="question-layout"><section class="quiz-card"><div class="section-head"><span class="chapter-tag">CHAPTER ${q.chapter} · LESSON ${q.topic}</span><span class="small muted">${quiz.index+1} / ${quiz.list.length}</span></div><div class="progressbar"><span style="width:${quiz.index/quiz.list.length*100}%"></span></div><h2>${esc(q.prompt)}</h2>${q.type==='choice'?`<div id="choices">${quiz.order.map((v,i)=>`<button class="choice" data-choice="${v}"><span>${String.fromCharCode(65+i)}</span>${esc(q.choices[v])}</button>`).join('')}</div>`:`<label for="numeric-answer">Your answer in ${esc(q.unit||'the requested unit')}</label><div class="answer-field"><input id="numeric-answer" inputmode="decimal" autocomplete="off" placeholder="Enter your value"><span>${esc(q.unit||'')}</span></div>`}<div id="feedback" aria-live="polite"></div><div class="quiz-controls"><span class="tiny muted">Take your time. Check your reasoning.</span><button class="button primary" id="check-answer">Check answer →</button></div></section><aside class="panel"><div class="eyebrow">A USEFUL HABIT</div><h3>Before you calculate</h3><p>Sketch the circuit, label reference directions, and write what is known.</p><p class="tiny muted" id="quiz-score-summary">Correct so far: ${quiz.score} of ${quiz.answers.length}. Practice results stay on this device.</p><a class="text-link" href="#method/${methods.find(m=>m.topic===q.topic)?.id||'units'}">Need a method? ↗</a></aside></div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(quiz.checked)return;quiz.selected=Number(b.dataset.choice);document.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b));saveQuiz()});$('#end-session').onclick=()=>{quiz=null;saveQuiz();};document.querySelectorAll('[data-choice]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.choice)===quiz.selected));if($('#numeric-answer')){$('#numeric-answer').value=quiz.numericText||'';$('#numeric-answer').oninput=e=>{quiz.numericText=e.target.value;saveQuiz();};}saveQuiz();$('#check-answer').onclick=checkAnswer;if(quiz.checked)showQuizFeedback(quiz.answers[quiz.answers.length-1]);$('#numeric-answer')?.addEventListener('keydown',e=>{if(e.key==='Enter')checkAnswer()});bindStudyState();}
function checkAnswer(){if(quiz.checked)return;let q=quiz.list[quiz.index],given=q.type==='choice'?quiz.selected:parseNumber($('#numeric-answer').value);if(given===null||!Number.isFinite(given)){toast('Enter or select an answer first.');return}let correct=q.type==='choice'?given===q.answer:Math.abs(given-q.value)<=(q.tol??Math.max(.005,Math.abs(q.value)*.01));quiz.checked=true;quiz.score+=correct?1:0;quiz.answers.push({id:q.id,correct,given});let old=state.attempts[q.id]||{tries:0,correct:0};state.attempts[q.id]={tries:old.tries+1,correct:old.correct+(correct?1:0),lastCorrect:correct,lastAt:Date.now()};save();saveQuiz();showQuizFeedback({given,correct});}
function showQuizFeedback({given,correct}){const q=quiz.list[quiz.index];if($('#quiz-score-summary'))$('#quiz-score-summary').textContent='Correct so far: '+quiz.score+' of '+quiz.answers.length+'. Practice results stay on this device.';document.querySelectorAll('[data-choice]').forEach(b=>{b.classList.toggle('correct',Number(b.dataset.choice)===q.answer);b.classList.toggle('wrong',!correct&&Number(b.dataset.choice)===given);b.disabled=true});if($('#numeric-answer'))$('#numeric-answer').disabled=true;$('#feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${correct?'Correct.':'Let’s repair this step.'}</strong><p>${esc(q.explain)}</p><p><strong>Answer:</strong> ${esc(q.type==='choice'?q.choices[q.answer]:q.value+' '+(q.unit||''))}</p>${link(q.topic,'Review the complete explanation')}</div>`;let b=$('#check-answer');b.textContent=quiz.index===quiz.list.length-1?'See results →':'Next question →';b.onclick=()=>{quiz.index++;quiz.order=null;quiz.selected=null;quiz.checked=false;quiz.numericText='';saveQuiz();if(quiz.index===quiz.list.length)showResults();else drawQuestion()}}
function showResults(){let misses=quiz.answers.filter(a=>!a.correct);$('#main').innerHTML=`<section class="panel"><div class="eyebrow">SESSION COMPLETE</div><div class="result-score">${quiz.score}<span class="muted"> / ${quiz.list.length}</span></div><h1>${misses.length?'Your next steps are clear.':'A good session. Keep the reasoning.'}</h1><p>${misses.length?'Return to these explanations, then try again without looking.':'Revisit these ideas later and apply them to a fresh circuit.'}</p>${misses.map(a=>{let q=questions.find(q=>q.id===a.id);return `<div class="mistake-row"><p>${esc(q.prompt)}</p>${link(q.topic)}</div>`}).join('')}<div class="button-row">${button('#practice/mistakes','Revisit mistakes','primary')}<a class="button" href="#practice" data-new-session>Another session</a>${button('#exam','Open exam sheet')}</div><p class="tiny muted">This is a practice result, not an estimate of your exam grade.</p></section>`;bindStudyState();}
function exam(){return `<div class="exam-banner"><div class="eyebrow">YOUR OPEN-BOOK DESK</div><h1>Find the right equation.<br>Keep its conditions beside it.</h1><p>Complete formula reference and a last-minute checking routine.</p><div class="button-row">${pdf}<button class="button" id="print">Print this exam sheet</button>${button('#methods','Find a method →')}</div></div><div class="priority-note">Your teacher has not specified topic weightings. This sheet follows the full reviewed course; method suggestions reflect its problem types.</div><div class="section-head"><h2>Recognize the question</h2></div><div class="grid3">${[['Equivalent seen by a load','thevenin'],['After a switch changes','transient'],['Sinusoids, phase or power','phasor']].map(([s,id])=>`<a class="panel" href="#method/${id}"><h3>${s}</h3><span class="text-link">Open the method →</span></a>`).join('')}</div><div class="section-head"><h2>Formula reference</h2><button class="text-link" id="formula-search">Search all content ⌕</button></div>${[...new Set(window.FORMULAS.map(f=>f[0]))].map(group=>`<h3>${group}</h3><div class="formula-grid">${window.FORMULAS.filter(f=>f[0]===group).map(f=>`<article class="formula-card"><h4>${f[1]}</h4><div class="formula">${f[2]}</div><p>${f[3]}</p>${link(f[4],'Lesson '+f[4])}</article>`).join('')}</div>`).join('')}<section class="panel" style="margin-top:28px"><h2>Before you hand it in</h2><div class="checklist">${['Reference directions and voltage polarities are labeled.','Independent sources are deactivated correctly; controlled sources remain active.','Initial conditions and the post-switch circuit are distinguished.','RMS and peak values are not mixed; sine-based phase references are consistent.','Units, signs, limiting values and power balance make sense.','The requested answer has its unit and physical interpretation.'].map(s=>`<label><input type="checkbox"> ${s}</label>`).join('')}</div></section>`}
let labMode=CircuitStore.get('lab')?.mode==='ac'?'ac':'rc';
function lab(){return `<div class="page-intro"><div class="eyebrow">SEE THE EQUATION CHANGE</div><h1>Make the circuit respond.</h1><p>Move one value at a time. Predict the result, then compare it with the graph.</p></div><div class="filter-row"><button class="filter ${labMode==='rc'?'active':''}" data-lab="rc">RC charging</button><button class="filter ${labMode==='ac'?'active':''}" data-lab="ac">Series RLC phasor</button></div><section class="panel"><div id="lab-controls" class="lab-controls">${labMode==='rc'?slider('r','Resistance R',1,20,5,1,'kΩ')+slider('c','Capacitance C',10,200,100,10,'µF')+slider('t','Observe at t/τ',0,5,1,.1,'τ'):slider('r','Resistance R',0,100,30,1,'Ω')+slider('l','Inductive reactance XL',0,100,60,1,'Ω')+slider('c','Capacitive reactance XC',0,100,20,1,'Ω')}</div><div id="lab-output"></div></section><p class="skills-note">These are ideal circuit models. The complete lessons cover the assumptions and further cases. ${link(labMode==='rc'?'2.3':'3.4')}</p>`}
function slider(id,label,min,max,value,step,unit){const saved=CircuitStore.get('lab')?.values?.[labMode]?.[id];if(Number.isFinite(saved))value=Math.max(min,Math.min(max,saved));return `<div><label class="range-label" for="lab-${id}">${label}<strong id="val-${id}">${value} ${unit}</strong></label><input type="range" id="lab-${id}" min="${min}" max="${max}" value="${value}" step="${step}" data-unit="${unit}"></div>`}
function updateLab(){const stored=CircuitStore.get('lab')||{values:{}};stored.values??={};stored.mode=labMode;stored.values[labMode]=Object.fromEntries([...document.querySelectorAll('#lab-controls input')].map(e=>[e.id.slice(4),Number(e.value)]));CircuitStore.set('lab',stored);document.querySelectorAll('#lab-controls input').forEach(e=>$('#val-'+e.id.slice(4)).textContent=e.value+' '+e.dataset.unit);let r=Number($('#lab-r').value),c=Number($('#lab-c').value),out='';if(labMode==='rc'){let t=Number($('#lab-t').value),v=rc(r,c,t),x=60+t*100,y=250-v.voltage*20;let path=Array.from({length:101},(_,i)=>`${i?'L':'M'}${60+i*5},${250-200*(1-Math.exp(-i/20))}`).join(' ');out=`<svg class="lab-svg" viewBox="0 0 640 300" role="img" aria-label="Capacitor voltage rises exponentially from zero toward ten volts. At one time constant it reaches 6.32 volts."><path d="M60 40V250H590" fill="none" stroke="#929f93"/><path d="M60 50H560" stroke="#bdc6ba" stroke-dasharray="5 5"/><path d="${path}" fill="none" stroke="#20594d" stroke-width="4"/><path d="M${x} 250V${y}" stroke="#aa6246" stroke-dasharray="4 4"/><circle cx="${x}" cy="${y}" r="6" fill="#aa6246"/><g font-family="monospace" font-size="14" fill="#52645a"><text x="7" y="55">10 V</text><text x="25" y="255">0</text>${[1,2,3,4,5].map(i=>`<text x="${50+i*100}" y="277">${i}τ</text>`).join('')}<text x="65" y="26">uC(t)</text></g></svg><div class="metric-row"><div class="metric"><span>Time constant τ = RC</span><strong>${(v.tau/1000).toFixed(2)} s</strong></div><div class="metric"><span>Capacitor voltage</span><strong>${v.voltage.toFixed(2)} V</strong></div><div class="metric"><span>Current at ${t}τ</span><strong>${v.current.toFixed(3)} mA</strong></div></div><div class="lab-description"><h3>R changes the pace. The final value stays 10 V.</h3><p>uC(t) = 10(1 − e⁻ᵗ/τ), with uC(0⁺) = 0 V and uC(∞) = 10 V. At ${t}τ, physical time is ${(t*v.tau/1000).toFixed(3)} s. The initial current is ${(10/r).toFixed(2)} mA.</p><p>At a fixed fraction of τ the voltage fraction is unchanged when R or C changes. At a fixed physical time, it changes. Charging current falls as the capacitor fills.</p></div>`}else{let l=Number($('#lab-l').value),v=phasor(r,l,c),scale=1.7,ox=150,oy=160,ex=ox+r*scale,ey=oy-v.x*scale;out=`<svg class="lab-svg" viewBox="0 0 640 300" role="img" aria-label="Impedance triangle: resistance lies on the real axis, net reactance on the imaginary axis."><path d="M70 160H500M150 285V15" stroke="#bdc6ba"/><path d="M${ox} ${oy}H${ex}" stroke="#20594d" stroke-width="5"/><path d="M${ex} ${oy}V${ey}" stroke="#aa6246" stroke-width="5"/><path d="M${ox} ${oy}L${ex} ${ey}" stroke="#203a35" stroke-width="3"/><circle cx="${ex}" cy="${ey}" r="5" fill="#203a35"/><g font-family="monospace" font-size="15" fill="#52645a"><text x="505" y="166">Re (Ω)</text><text x="160" y="25">+jX</text><text x="160" y="285">−jX</text><text x="${ex+12}" y="${Math.max(40,Math.min(270,ey))}">Z</text></g></svg><div class="metric-row"><div class="metric"><span>|Z| = √(R² + X²)</span><strong>${v.z.toFixed(2)} Ω</strong></div><div class="metric"><span>Impedance angle φ</span><strong>${v.z?v.angle.toFixed(1)+'°':'Undefined'}</strong></div><div class="metric"><span>Current, U = 100 V RMS</span><strong>${v.i===null?'No finite value':v.i.toFixed(2)+' A'}</strong></div></div><div class="lab-description"><h3>${v.x>0?'Net inductive: current lags voltage.':v.x<0?'Net capacitive: current leads voltage.':r?'Reactances cancel: current is in phase.':'Zero ideal impedance: the model has no finite current.'}</h3><p>Z = ${r} + j(${l} − ${c}) = ${r} ${v.x<0?'−':'+'} j${Math.abs(v.x)} Ω. Current phase relative to voltage is ${v.z?(-v.angle).toFixed(1)+'°':'undefined'}.</p><p>${v.i===null?'Add resistance or nonzero net reactance to calculate a finite current.':`P = ${v.p.toFixed(1)} W · Q = ${v.q.toFixed(1)} var · S = ${(100*v.i).toFixed(1)} VA. Positive Q is inductive; negative Q is capacitive.`}</p></div>`}$('#lab-output').innerHTML=out}
function openModal(html){const prior=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Study studio dialog"><button class="modal-close" aria-label="Close dialog">×</button>${html}</section></div>`;const close=()=>{$('#overlay').innerHTML='';prior?.focus()};$('.modal-close').onclick=close;$('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)close()};$('.modal').onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){let f=[...$('.modal').querySelectorAll('button,input,a[href]')],first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};$('.modal-close').focus();return close}
function openSearch(){let close=openModal(`<div class="modal-head"><div class="eyebrow">YOUR WHOLE COURSE, ONE SEARCH</div><h2>What do you need to find?</h2></div><input class="search-box" type="search" id="global-search" aria-label="Search chapters, methods and formulas" placeholder="Try Thévenin, initial condition, RMS…"><div id="search-results" class="search-results"></div>`);const run=()=>{let term=$('#global-search').value.toLowerCase().trim(),words=term.split(/\s+/).filter(Boolean);let items=[...methods.map(m=>({title:m.title,text:m.cue+' '+m.tags,href:'#method/'+m.id,type:'SOLVING METHOD'})),...topics.map(t=>({title:t.id+' '+t.title,text:t.text,href:'#topic/'+t.id,type:'COMPLETE LESSON'})),...window.FORMULAS.map(f=>({title:f[1],text:f[2]+' '+f[3],href:'#topic/'+f[4],type:'FORMULA · LESSON '+f[4]}))].map(item=>({...item,score:words.reduce((s,w)=>s+(item.title.toLowerCase().includes(w)?6:0)+(item.text.toLowerCase().includes(w)?1:0),0)})).filter(i=>!term||i.score>0).sort((a,b)=>b.score-a.score).slice(0,10);$('#search-results').innerHTML=items.length?items.map(i=>`<a class="search-result" href="${i.href}"><span class="chapter-tag">${i.type}</span><strong>${esc(i.title)}</strong><span class="tiny muted">${esc(i.text.replace(/<[^>]+>/g,'').slice(0,135))}…</span></a>`).join(''):'<div class="empty">No matches. Try a shorter term, a symbol name, or the lesson number.</div>';document.querySelectorAll('.search-result').forEach(a=>a.onclick=close)};$('#global-search').oninput=run;run();$('#global-search').focus()}
function about(){openModal(`<div class="eyebrow">BUILT FOR YOUR OPEN-BOOK EXAM</div><h2>Understand. Locate. Apply. Check.</h2><p>Use the problem finder to recognize a method, the complete library to understand it, and practice to check what you can do independently.</p><h3>What is covered?</h3><p>All 20 indexed theory lessons, organized into 21 study topics because the RL lesson is embedded in section 2.4. The guide reviews 24 documents and 330 slide pages across three chapters. Experiments are excluded.</p><p>The full reviewed PDF remains available. The course’s sine-based RMS phasor convention is preserved, and the guide identifies corrections to misleading slide captions or numerical rounding.</p><h3>Why this learning design?</h3><p>Worked examples are paired with attempts, graphs with explanations, and answers with feedback. Return to the same ideas over several days. These choices follow evidence-informed study guidance; they do not guarantee an exam result.</p><p><a class="text-link" target="_blank" rel="noopener" href="https://ies.ed.gov/ncee/wwc/PracticeGuide/1">IES: Organizing Instruction and Study to Improve Student Learning ↗</a></p><p><a class="text-link" target="_blank" rel="noopener" href="https://pubmed.ncbi.nlm.nih.gov/21252317/">Karpicke & Blunt (2011): retrieval practice study ↗</a></p><h3>Your progress stays here</h3><p>Review marks and practice attempts are stored in this browser on this device. Clearing browser data removes them. There is no account-based progress sync.</p>${pdf}`)}
function render(){const parts=(location.hash.slice(1)||'desk').split('/'),route=parts[0],id=parts[1];window.ChapterOne?.stop();window.CircuitFoundation?.unmount();window.CircuitVideos?.unmount();document.documentElement.classList.toggle('chapter-one-reading',(route==='topic')||(route==='chapter'&&[1,2,3].includes(Number(id))));shell(route);const main=$('#main');if(route==='topic'){const selected=topic(id)||topics[0];if(selected.chapter===1){state.lastTopic=selected.id;save();main.innerHTML=window.ChapterOne.page(selected,state.reviewed.includes(selected.id));}else if(window.CourseLessons?.supports(selected.id)){state.lastTopic=selected.id;save();main.innerHTML=window.CourseLessons.page(selected,state.reviewed.includes(selected.id));}else if(window.CourseLessons?.supports(selected.id)){state.lastTopic=selected.id;save();main.innerHTML=window.CourseLessons.page(selected,state.reviewed.includes(selected.id));}else main.innerHTML=library(id);$('#review-topic').onclick=()=>{let t=topic(id)||topics[0],i=state.reviewed.indexOf(t.id);if(i<0)state.reviewed.push(t.id);else state.reviewed.splice(i,1);save();render()}}
else if(route==='chapter')main.innerHTML=Number(id)===1?window.ChapterOne.overview():window.CourseLessons?.overview(Number(id))||chapterPage(id);
else if(route==='chapters')main.innerHTML=chaptersPage();
else if(route==='methods'){main.innerHTML=methodsPage();let chapter=0;const filter=()=>{let words=$('#method-search').value.toLowerCase().trim().split(/\s+/);let list=methods.filter(m=>(!chapter||m.chapter===chapter)&&words.every(w=>(m.title+' '+m.cue+' '+m.tags).toLowerCase().includes(w)));$('#method-results').innerHTML=list.length?methodCards(list):'<div class="empty">No methods match. Try the complete course search.</div>'};$('#method-search').oninput=filter;document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{chapter=Number(b.dataset.chapter);document.querySelectorAll('[data-chapter]').forEach(x=>x.classList.toggle('active',x===b));filter()})}
else if(route==='method')main.innerHTML=methodDetail(id);
else if(route==='practice'){let f=parts.slice(1).join('/');if(quiz&&quiz.filter===f){if(quiz.index>=quiz.list.length)showResults();else drawQuestion();}else{main.innerHTML=practiceIntro(f);$('#start-quiz').onclick=()=>beginQuiz(false,f);$('#start-all').onclick=()=>beginQuiz(true,f);}}
else if(route==='exam'){main.innerHTML=exam();$('#print').onclick=()=>window.print();$('#formula-search').onclick=openSearch}
else if(route==='lab'){main.innerHTML=lab();document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>{labMode=b.dataset.lab;render()});document.querySelectorAll('#lab-controls input').forEach(x=>x.oninput=updateLab);updateLab()}
else main.innerHTML=desk();bindReadingControls();if(document.querySelector('#course-lesson')){window.CourseLessons.mount();window.CircuitGuided?.mount();}else if(document.querySelector('#course-lesson')){window.CourseLessons.mount();window.CircuitGuided?.mount();}else if(document.documentElement.classList.contains('chapter-one-reading')){window.ChapterOne.mount({onAttempt:(q,correct)=>{const old=state.attempts[q.id]||{tries:0,correct:0};state.attempts[q.id]={tries:old.tries+1,correct:old.correct+Number(correct),lastCorrect:correct,lastAt:Date.now()};save();}});}else window.CircuitGuided?.mount();main.insertAdjacentHTML('beforeend','<footer class="footer"><span>Circuit Exam Studio</span><span>Source-based · exam-focused · yours to explore</span></footer>');bindStudyState();window.scrollTo(0,(CircuitStore.get('positions')||{})[location.hash]?.scroll||0)}
function bindStudyState(){
 const main=$('#main');/* C1_PRACTICE_RETURN_START */const c1Practice=location.hash.match(/^#practice\/topic\/([123]\.(?:10|[1-9]))$/);if(c1Practice&&!main.querySelector('#c1-return-lesson'))main.insertAdjacentHTML('afterbegin',`<a class="backlink" id="c1-return-lesson" href="#topic/${c1Practice[1]}">← Lesson ${c1Practice[1]} · video & cheat sheet</a>`);/* C1_PRACTICE_RETURN_END */main.querySelector('.study-save-strip')?.remove();main.insertAdjacentHTML('beforeend','<div class="study-save-strip"><span data-study-save role="status"></span><button data-export-study>Export backup</button><label class="import-label">Import backup<input type="file" data-import-study accept="application/json" hidden></label><button data-protect-study>Protect saved work</button></div>');document.querySelectorAll('[data-study-save]').forEach(el=>el.textContent=CircuitStore.status());
 const checklist=CircuitStore.get('checklist')||{};document.querySelectorAll('.checklist input').forEach((input,i)=>{input.checked=!!checklist[i];input.onchange=()=>{checklist[i]=input.checked;CircuitStore.set('checklist',checklist);};});
 const ui=CircuitStore.get('ui')||{};if(ui.route!==location.hash){ui.route=location.hash;CircuitStore.set('ui',ui);}for(const id of ['method-search','quiz-chapter']){const input=$('#'+id);if(!input)continue;if(ui[id]!==undefined){input.value=ui[id];if(id==='method-search')input.dispatchEvent(new Event('input'));}input.addEventListener('input',()=>{ui[id]=input.value;CircuitStore.set('ui',ui);});}
}
let scrollTimer;window.addEventListener('scroll',()=>{clearTimeout(scrollTimer);const hash=location.hash,scroll=window.scrollY;scrollTimer=setTimeout(()=>{const positions=CircuitStore.get('positions')||{};positions[hash]={scroll};CircuitStore.set('positions',positions);},180);},{passive:true});
function navigate(){const ui=CircuitStore.get('ui')||{};ui.route=location.hash;CircuitStore.set('ui',ui);focusNavigationOpen=false;render();const heading=$('#main h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
document.addEventListener('click',e=>{if(e.target.closest('[data-new-session]')){quiz=null;saveQuiz();}const a=e.target.closest('a[href^="#"]');if(a&&a.getAttribute('href')===location.hash){e.preventDefault();navigate()}});window.addEventListener('hashchange',navigate);document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('#global-search')){e.preventDefault();openSearch()}});if(!location.hash){const last=(CircuitStore.get('ui')||{}).route;if(/^#(?:desk|chapters|chapter|topic|methods|method|practice|exam|lab)(?:\/[a-zA-Z0-9.\/-]+)?$/.test(last||''))history.replaceState(null,'',last);}render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});
})();
